-- READ ONLY audit; all statements SELECT. Project dkyfkdmlkghucyepxbbh. Re-run before approval.
SELECT table_schema,table_name,ordinal_position,column_name,data_type,udt_name,is_nullable,column_default,identity_generation FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('profiles','categories','resources','borrow_requests') ORDER BY table_name,ordinal_position;
SELECT n.nspname,c.relname,c.relrowsecurity,c.relforcerowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('profiles','categories','resources','borrow_requests');
SELECT schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND tablename IN ('profiles','categories','resources','borrow_requests') ORDER BY tablename,cmd,policyname;
SELECT table_schema,table_name,grantee,privilege_type,is_grantable FROM information_schema.table_privileges WHERE table_schema='public' AND table_name IN ('profiles','categories','resources','borrow_requests') AND grantee IN ('PUBLIC','anon','authenticated') ORDER BY table_name,grantee,privilege_type;
SELECT n.nspname,c.relname,a.attname,a.attacl FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('profiles','categories','resources','borrow_requests') AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL;
SELECT r.rolname,n.nspname,d.defaclobjtype,d.defaclacl FROM pg_default_acl d JOIN pg_roles r ON r.oid=d.defaclrole LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE d.defaclnamespace=(SELECT oid FROM pg_namespace WHERE nspname='public') OR d.defaclnamespace=0;
SELECT con.conrelid::regclass,con.conname,con.contype,con.confrelid::regclass,con.confdeltype,con.confupdtype,pg_get_constraintdef(con.oid,true) FROM pg_constraint con WHERE con.conrelid IN ('public.profiles'::regclass,'public.categories'::regclass,'public.resources'::regclass,'public.borrow_requests'::regclass) ORDER BY con.conrelid::regclass::text,con.contype,con.conname;
SELECT schemaname,tablename,indexname,indexdef FROM pg_indexes WHERE schemaname='public' AND tablename IN ('profiles','categories','resources','borrow_requests') ORDER BY tablename,indexname;
SELECT con.conrelid::regclass,con.conname,pg_get_constraintdef(con.oid,true) FROM pg_constraint con WHERE con.contype='c' AND con.conrelid IN ('public.profiles'::regclass,'public.categories'::regclass,'public.resources'::regclass,'public.borrow_requests'::regclass);
-- Trigger/function definitions only, no Auth records or secrets.
SELECT t.tgrelid::regclass,t.tgname,pg_get_triggerdef(t.oid,true),p.oid::regprocedure,pg_get_userbyid(p.proowner),p.prosecdef,p.proconfig,p.proacl,pg_get_functiondef(p.oid) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND t.tgrelid='auth.users'::regclass;
SELECT n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),pg_get_userbyid(p.proowner),p.prosecdef,p.proconfig,p.proacl,has_function_privilege('anon',p.oid,'EXECUTE'),has_function_privilege('authenticated',p.oid,'EXECUTE'),pg_get_functiondef(p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prosecdef ORDER BY p.proname;
-- Aggregate counts only; recheck before adding unique pending index.
SELECT (SELECT count(*) FROM public.categories) categories,(SELECT count(*) FROM public.profiles) profiles,(SELECT count(*) FROM public.resources) resources,(SELECT count(*) FROM public.borrow_requests) requests,(SELECT count(*) FROM public.profiles WHERE btrim(full_name)='') blank_names,(SELECT count(*) FROM (SELECT borrower_id,resource_id FROM public.borrow_requests WHERE status='pending' GROUP BY borrower_id,resource_id HAVING count(*)>1)d) duplicate_pending_pairs,(SELECT count(*) FROM public.borrow_requests br JOIN public.resources r ON r.id=br.resource_id WHERE br.status='pending' AND (br.borrower_id=r.owner_id OR r.availability_status<>'available')) pending_invalid;
